function validate(input) {
  const [obj1, obj2] = input;
  for (const value of [obj1, obj2]) {
    const text = JSON.stringify(value);
    if (text === undefined || text.length > 500000) return 'obj1 and obj2 must be JSON values of at most 500,000 characters.';
    const stack = [[value, 1]];
    while (stack.length) {
      const [item, depth] = stack.pop();
      if (item === null || typeof item !== 'object') continue;
      if (depth > 100) return 'Keep obj1 and obj2 at most 100 levels deep.';
      if (!Array.isArray(item) && Object.hasOwn(item, '__proto__')) return 'Keys named "__proto__" are not allowed.';
      for (const key of Object.keys(item)) stack.push([item[key], depth + 1]);
    }
  }
  return null;
}

