  const names = ['a', 'b', 'c', 'd', 'x'];
  let budget = small ? 14 : 1800;
  const primitive = () => {
    const roll = rand();
    if (roll < 0.45) return Math.floor(rand() * 10) - 3;
    if (roll < 0.65) return pick(['', 'a', 'z']);
    if (roll < 0.8) return rand() < 0.5;
    return null;
